// Pure scheduler core for Automations (#142). No React / no Tauri here — just the
// data model and the deterministic logic (next-run computation, target
// resolution, payload building) so it can be unit-tested in isolation. The tick
// loop and PTY dispatch live in useScheduler; CRUD lives in the store.

import { nextCronRun } from "@/features/automations/lib/cron";
import { clamp } from "@/shared/lib/core/math";

export type Every = "minute" | "hour" | "day" | "weekday";
export type AutomationActionKind = "command";
export type RunStatus = "ok" | "skipped" | "fail";

export interface SimpleWhen {
  kind: "simple";
  every: Every;
  /** "HH:MM" for day/weekday; ":MM" or "MM" for hour; ignored for minute. */
  at: string;
}
export interface CronWhen {
  kind: "cron";
  /** Standard 5-field cron expression. */
  expr: string;
}
export type AutomationWhen = SimpleWhen | CronWhen;

export interface AutomationRun {
  at: number;        // epoch ms
  status: RunStatus;
  note: string;
}

export interface Automation {
  id: string;
  name: string;
  armed: boolean;
  when: AutomationWhen;
  /** Tab resolved at fire time by name (survives reordering); pane by index. */
  targetTab: string;
  targetPaneIdx: number;
  action: AutomationActionKind;
  command?: string;   // action === "command"
  lastRunAt: number | null;
  nextRunAt: number | null;
  runs: AutomationRun[];
}

/** Parse the minute component out of an hour spec ("15", ":15", "x:15"). */
function parseMinute(at: string): number {
  const m = at.replace(/^.*:/, "").trim();
  const n = parseInt(m, 10);
  return Number.isFinite(n) ? clamp(n, 0, 59) : 0;
}

/** Parse "HH:MM" into [hours, minutes], clamped; missing parts default to 0. */
function parseHourMinute(at: string): [number, number] {
  const [h, m] = at.split(":");
  const hh = clamp(parseInt(h ?? "0", 10) || 0, 0, 23);
  const mm = clamp(parseInt(m ?? "0", 10) || 0, 0, 59);
  return [hh, mm];
}

function isWeekend(d: Date): boolean {
  const day = d.getDay();
  return day === 0 || day === 6; // Sun or Sat
}

/**
 * The next fire time strictly after `fromMs`, in local time, or null if the
 * spec is unsupported. v1 supports minute/hour/day/weekday; week/month are a
 * follow-up.
 */
export function computeNextRun(when: AutomationWhen, fromMs: number): number | null {
  if (when.kind === "cron") return nextCronRun(when.expr, fromMs);

  const from = new Date(fromMs);

  if (when.every === "minute") {
    // Next whole-minute boundary after `from`.
    return Math.floor(fromMs / 60000) * 60000 + 60000;
  }

  if (when.every === "hour") {
    const mm = parseMinute(when.at);
    const c = new Date(from);
    c.setSeconds(0, 0);
    c.setMinutes(mm);
    if (c.getTime() <= fromMs) c.setHours(c.getHours() + 1);
    return c.getTime();
  }

  if (when.every === "day" || when.every === "weekday") {
    const [hh, mm] = parseHourMinute(when.at);
    const c = new Date(from);
    c.setSeconds(0, 0);
    c.setHours(hh, mm);
    if (c.getTime() <= fromMs) c.setDate(c.getDate() + 1);
    if (when.every === "weekday") {
      while (isWeekend(c)) c.setDate(c.getDate() + 1);
    }
    return c.getTime();
  }

  return null;
}

export interface CarriedSchedule {
  personaId: string;
  name: string;
  when: AutomationWhen;
  command: string;
}

/** The log key for one carried schedule — `<persona>:<name>`. */
export function scheduleKey(personaId: string, name: string): string {
  return `${personaId}:${name}`;
}

/**
 * Which of the schedules the personas carry are due NOW, given when each last fired.
 *
 * STATELESS. It replaced `dueAutomations`, which read a mutable `nextRunAt` kept on the automation
 * record and rewritten after every fire. Due-ness is now derived from the LOG: the last fire is a
 * line in the automation stream, and the next is `computeNextRun` from it. That deletes
 * `nextRunAt`, `lastRunAt` and `runs[]` as stored state — and with them the class of bug where the
 * bookkeeping and the history disagree about whether something ran.
 *
 * A schedule that has NEVER fired is anchored at `nowMs`, not at the epoch. Anchoring at 0 would
 * make every newly-authored job overdue by decades and fire it the moment it is saved — a daily
 * 02:00 job authored at 10:00 should first run at 02:00 tomorrow, not immediately.
 */
export function duePersonaSchedules(
  carried: CarriedSchedule[],
  lastRuns: Record<string, number>,
  nowMs: number,
): CarriedSchedule[] {
  return carried.filter((s) => {
    const last = lastRuns[scheduleKey(s.personaId, s.name)];
    if (last == null) return false;              // never fired: anchored forward, not overdue
    const next = computeNextRun(s.when, last);
    return next != null && next <= nowMs;
  });
}

/** Keep at most this many run records per legacy automation. */
export const MAX_RUNS = 25;

/**
 * Append a run to a LEGACY automation record (newest first, capped).
 *
 * The scheduler no longer calls this: a schedule is carried by a persona and its runs are lines
 * in the `automation` log stream. This survives only for the `automations` store slice, which the
 * MOBILE TUNNEL still ships (`buildAutomationsPayload` + the phone's arm / run-now controls) —
 * a byte-shaped contract with mobile-studio-code that cannot be dropped from this side alone.
 *
 * So the slice is now DATA WITH NO RUNTIME EFFECT: nothing schedules from it. Retiring it needs a
 * coordinated change in both repos, tracked separately.
 */
export function appendRun(runs: AutomationRun[], run: AutomationRun): AutomationRun[] {
  return [run, ...runs].slice(0, MAX_RUNS);
}

/**
 * The pane a carried schedule fires into: the one running its CARRIER.
 *
 * Replaced `resolveTargetPane(targetTab, targetPaneIdx, …)`, which found a tab by NAME and a pane by
 * INDEX — and whose own comment conceded the index does not survive reordering. Moving a pane could
 * silently repoint a schedule at somebody else's terminal; now it cannot, because the target is an
 * identity rather than a position.
 */
export function resolvePersonaPane(
  personaId: string,
  panePersonas: Record<string, string>,
  disabledPanes: Record<string, boolean>,
): string | null {
  const paneId = Object.keys(panePersonas).find((p) => panePersonas[p] === personaId);
  if (!paneId || disabledPanes[paneId]) return null;
  return paneId;
}

export function suggestionToAutomation(
  s: { name: string; command: string; schedule?: string },
  targetTab: string,
): Omit<Automation, "id" | "lastRunAt" | "nextRunAt" | "runs"> {
  const when: AutomationWhen = s.schedule
    ? { kind: "cron", expr: s.schedule }
    : { kind: "simple", every: "day", at: "09:00" };
  return {
    name: s.name,
    armed: !!s.schedule,
    when,
    targetTab,
    targetPaneIdx: 0,
    action: "command",
    command: s.command,
  };
}

